13	/// 三元组连接身份主键：控制器 + 12位句柄 + 连接代次（防御句柄复用串设备）
14	struct HciConnectionKey {
15	    std::string controller_id;
16	    uint16_t handle{0};
17	    uint32_t generation{0};
18	
19	    bool operator==(const HciConnectionKey& other) const {
20	        return controller_id == other.controller_id &&
21	               handle == other.handle &&
22	               generation == other.generation;
23	    }
24	};
25	
26	struct HciConnectionKeyHash {
27	    std::size_t operator()(const HciConnectionKey& k) const {
28	        std::size_t h1 = std::hash<std::string>{}(k.controller_id);
29	        std::size_t h2 = std::hash<uint16_t>{}(k.handle);
30	        std::size_t h3 = std::hash<uint32_t>{}(k.generation);
31	        return h1 ^ (h2 << 1) ^ (h3 << 2);
32	    }
33	};
