1	/*
2	 * 文件: server/src/bpf/bt_hci_traffic.bpf.c
3	 * 职责: 工业蓝牙 HCI ACL 数据通道观测（Phase 1 事实源）
4	 *
5	 * 核心设计:
6	 *   1. 双向对称采集:
7	 *      - TX: kprobe/hci_send_frame
8	 *      - RX: kprobe/hci_recv_frame
9	 *   2. 严格防御过滤:
10	 *      - 在解引用数据前，读取 skb->cb 的 pkt_type，仅放行 HCI_ACLDATA_PKT (0x02)
11	 *      - 严格校验 skb->len >= 4
12	 *   3. 精准事实提取:
13	 *      - handle: 提取低 12 位 (raw_handle & 0x0FFF)
14	 *      - bytes:  累加 dlen (ACL 净荷字节数，不计物理层/HCI 传输开销)
15	 *   4. 零音频语义、零硬编码结构体偏移，原生依赖内核网络核心 sk_buff (CO-RE 友好)
16	 */
17	
18	#define __TARGET_ARCH_arm64
19	#include "vmlinux.h"
20	#include <bpf/bpf_helpers.h>
21	#include <bpf/bpf_core_read.h>
22	#include <bpf/bpf_tracing.h>
23	
24	char LICENSE[] SEC("license") = "GPL";
25	
26	#define HCI_ACLDATA_PKT 0x02
27	
28	struct bpf_acl_traffic_val {
29	    __u64 tx_packets;
30	    __u64 tx_bytes;
31	    __u64 rx_packets;
32	    __u64 rx_bytes;
33	    __u64 last_tx_ktime_ns;
34	    __u64 last_rx_ktime_ns;
35	    __u64 non_acl_dropped;
36	    __u64 short_pkt_dropped;
37	};
38	
39	// 以 connection_handle (低 12 位，取值 0..4095) 为 Key 记录流量统计
40	struct {
41	    __uint(type, BPF_MAP_TYPE_HASH);
42	    __uint(max_entries, 64);
43	    __type(key, __u32);
44	    __type(value, struct bpf_acl_traffic_val);
45	} bt_acl_traffic SEC(".maps");
46	
47	// 全局开关与未归类统计
48	struct {
49	    __uint(type, BPF_MAP_TYPE_ARRAY);
50	    __uint(max_entries, 4);
51	    __type(key, __u32);
52	    __type(value, __u64);
53	} bt_acl_global_stats SEC(".maps");
54	
55	static __always_inline void bump_global_counter(__u32 idx, __u64 val) {
56	    __u64 *p = bpf_map_lookup_elem(&bt_acl_global_stats, &idx);
57	    if (p) {
58	        __sync_fetch_and_add(p, val);
59	    }
60	}
61	
62	// ----------------------------------------------------------------------------
63	// TX 挂点: kprobe/hci_send_frame(struct hci_dev *hdev, struct sk_buff *skb)
64	// ----------------------------------------------------------------------------
65	SEC("kprobe/hci_send_frame")
66	int BPF_KPROBE(bt_hci_send_frame, void *hdev, struct sk_buff *skb) {
67	    if (!skb) return 0;
68	
69	    // 1. 报文类型门控 (bt_cb(skb)->pkt_type 位于 skb->cb 第 0 字节)
70	    __u8 pkt_type = 0;
71	    if (bpf_probe_read_kernel(&pkt_type, sizeof(pkt_type),
72	                              (const char *)skb + offsetof(struct sk_buff, cb)) < 0) {
73	        return 0;
74	    }
75	
76	    if (pkt_type != HCI_ACLDATA_PKT) {
77	        bump_global_counter(0, 1); // TX 非 ACL 过滤
78	        return 0;
79	    }
80	
81	    // 2. 报文长度防御
82	    __u32 len = BPF_CORE_READ(skb, len);
83	    if (len < 4) {
84	        bump_global_counter(2, 1); // TX 短报文丢弃
85	        return 0;
86	    }
87	
88	    const unsigned char *data = BPF_CORE_READ(skb, data);
89	    if (!data) return 0;
90	
91	    // 3. 读取并解析 ACL 报头 (handle: 12bit, dlen: 16bit)
92	    __u16 raw_handle = 0;
93	    __u16 dlen = 0;
94	    if (bpf_probe_read_kernel(&raw_handle, sizeof(raw_handle), data) < 0) return 0;
95	    if (bpf_probe_read_kernel(&dlen, sizeof(dlen), data + 2) < 0) return 0;
96	
97	    __u32 handle = raw_handle & 0x0FFF;
98	
99	    // 4. 更新 Handle 统计
100	    struct bpf_acl_traffic_val *stat = bpf_map_lookup_elem(&bt_acl_traffic, &handle);
101	    if (!stat) {
102	        struct bpf_acl_traffic_val init = {};
103	        bpf_map_update_elem(&bt_acl_traffic, &handle, &init, BPF_NOEXIST);
104	        stat = bpf_map_lookup_elem(&bt_acl_traffic, &handle);
105	        if (!stat) return 0;
106	    }
107	
108	    __u64 now = bpf_ktime_get_ns();
109	    __sync_fetch_and_add(&stat->tx_packets, 1);
110	    __sync_fetch_and_add(&stat->tx_bytes, dlen);
111	    stat->last_tx_ktime_ns = now;
112	
113	    return 0;
114	}
115	
116	// ----------------------------------------------------------------------------
117	// RX 挂点: kprobe/hci_recv_frame(struct hci_dev *hdev, struct sk_buff *skb)
118	// ----------------------------------------------------------------------------
119	SEC("kprobe/hci_recv_frame")
120	int BPF_KPROBE(bt_hci_recv_frame, void *hdev, struct sk_buff *skb) {
121	    if (!skb) return 0;
122	
123	    // 1. 报文类型门控
124	    __u8 pkt_type = 0;
125	    if (bpf_probe_read_kernel(&pkt_type, sizeof(pkt_type),
126	                              (const char *)skb + offsetof(struct sk_buff, cb)) < 0) {
127	        return 0;
128	    }
129	
130	    if (pkt_type != HCI_ACLDATA_PKT) {
131	        bump_global_counter(1, 1); // RX 非 ACL 过滤 (如底噪 HCI Event)
132	        return 0;
133	    }
134	
135	    // 2. 报文长度防御
136	    __u32 len = BPF_CORE_READ(skb, len);
137	    if (len < 4) {
138	        bump_global_counter(3, 1); // RX 短报文丢弃
139	        return 0;
140	    }
141	
142	    const unsigned char *data = BPF_CORE_READ(skb, data);
143	    if (!data) return 0;
144	
145	    // 3. 读取并解析 ACL 报头
146	    __u16 raw_handle = 0;
147	    __u16 dlen = 0;
148	    if (bpf_probe_read_kernel(&raw_handle, sizeof(raw_handle), data) < 0) return 0;
149	    if (bpf_probe_read_kernel(&dlen, sizeof(dlen), data + 2) < 0) return 0;
150	
151	    __u32 handle = raw_handle & 0x0FFF;
152	
153	    // 4. 更新 Handle 统计
154	    struct bpf_acl_traffic_val *stat = bpf_map_lookup_elem(&bt_acl_traffic, &handle);
155	    if (!stat) {
156	        struct bpf_acl_traffic_val init = {};
157	        bpf_map_update_elem(&bt_acl_traffic, &handle, &init, BPF_NOEXIST);
158	        stat = bpf_map_lookup_elem(&bt_acl_traffic, &handle);
159	        if (!stat) return 0;
160	    }
161	
162	    __u64 now = bpf_ktime_get_ns();
163	    __sync_fetch_and_add(&stat->rx_packets, 1);
164	    __sync_fetch_and_add(&stat->rx_bytes, dlen);
165	    stat->last_rx_ktime_ns = now;
166	
167	    return 0;
