1	/**
2	 * @file bt_event_monitor.hpp
3	 * @brief 蓝牙设备事件采集器（eBPF ringbuf -> RawBtObservation -> 归一化器）
4	 *
5	 * 数据流位置：
6	 *
7	 *   bt_events.bpf.c（内核 kprobe）
8	 *        ↓ ringbuf（原始观测，非业务事件）
9	 *   BtEventMonitor::consumeLoop()      ← 本类
10	 *        ↓ 转换为 RawBtObservation
11	 *   BtEventNormalizer::submit()
12	 *        ↓ 同一故障的多条观测在时间窗内合并
13	 *   WirelessDeviceEvent → WirelessEventStore
14	 *
15	 * 关键设计（与 plan 的语义约束一致）：
16	 *
17	 *   1. **本类不产生业务事件**。它把内核观测转成 RawBtObservation 投给归一化器，
18	 *      由归一化器决定"多个 hook 观测到一次断连"最终产生几个业务事件。
19	 *      若在这里各 hook 自产事件，同一物理故障会被重复计数。
20	 *
21	 *   2. **逐个 hook 独立挂载、独立降级**。某个 kprobe 在内核上不存在
22	 *      （例如不同内核版本缺少 hci_conn_timeout）时，只记日志并跳过，
23	 *      其余 hook 继续工作，绝不整体失败。
24	 *
25	 *   3. **不做诊断推断**。suspected_cause 恒为空，由后续 Phase 的
26	 *      LinkAnomalyDetector 产生。
27	 *
28	 *   4. **不做 CO-RE 读蓝牙结构**。目标内核蓝牙是模块，hci_conn/l2cap_chan
29	 *      不在 vmlinux BTF 中；结构偏移来自板端模块 BTF 实锤，写在 .bpf.c 注释里。
30	 */
31	
32	#pragma once
33	
34	#include <atomic>
35	#include <cstdint>
36	#include <memory>
37	#include <mutex>
38	#include <string>
39	#include <thread>
40	#include <vector>
41	
42	#include "bt_event_normalizer.hpp"
43	#include "ebpf_monitor_interface.hpp"
44	#include "ebpf_monitor_metrics.hpp"
45	#include "wireless_event_store.hpp"
46	
47	struct bpf_object;
48	struct bpf_link;
49	struct ring_buffer;
50	
51	namespace weaknet_dbus {
52	
53	class BtLinkQualityTracker;  ///< 前置声明：Phase 2 RSSI 回填源
54	
55	/// 单个挂点的挂载结果（用于诊断日志与 health 上报）
56	struct BtHookStatus {
57	    std::string kernel_function;   ///< 内核函数名，如 "mgmt_device_disconnected"
58	    bool attached = false;         ///< 是否挂载成功
59	    std::string error;             ///< 失败原因（成功时为空）
60	};
61	
62	/**
63	 * @brief 蓝牙设备事件采集器
64	 */
65	class BtEventMonitor : public IEbpfMonitor {
66	public:
67	    /**
68	     * @param store   事件存储（不拥有所有权；可为 nullptr，此时只归一化不落库，
69	     *                用于单元测试/降级）
70	     * @param tracker 链路质量跟踪器（不拥有所有权；用于 Canonical 事件定案后的因果 RSSI 回填）
71	     */
72	    explicit BtEventMonitor(WirelessEventStore* store = nullptr,
73	                            BtLinkQualityTracker* tracker = nullptr,
74	                            BtNormalizerConfig normalizer_cfg = {});
75	    ~BtEventMonitor() override;
76	
77	    BtEventMonitor(const BtEventMonitor&) = delete;
78	    BtEventMonitor& operator=(const BtEventMonitor&) = delete;
79	
80	    /**
81	     * @brief 加载 eBPF 对象并逐个挂载 kprobe
82	     *
83	     * 至少一个 hook 挂载成功即视为可用；全部失败则进入 Fallback
84	     * （用户空间不崩溃，isAvailable() 返回 false）。
85	     *
86	     * @param bpf_object_path bt_events.bpf.o 路径
87	     * @param gateway_id      网关身份，写入每条观测（事件来源身份）
88	     * @return true 至少一个 hook 挂载成功
89	     */
90	    bool init(const std::string& bpf_object_path, const std::string& gateway_id);
91	
92	    /// 停止采集：停消费线程、detach 全部 hook、释放 BPF 对象
93	    void stop();
94	
95	    /// 启动 ringbuf 消费线程（init 成功后调用）
96	    bool start();
97	
98	    // ---- IEbpfMonitor 实现 ----
99	    const char* monitorName() const override { return "BtEventMonitor"; }
100	    EbpfMonitorState commonState() const override;
101	    bool isAvailable() const override;
102	    EbpfMonitorHealth health() const override { return stateSupport_.health(); }
103	    EbpfMonitorMetrics metrics() const override { return stateSupport_.metrics(); }
104	    void resetMetrics() override { stateSupport_.resetMetrics(); }
105	
106	    // ---- 诊断 ----
107	
108	    /// 全部挂点的挂载状态（含失败的及失败原因）
109	    std::vector<BtHookStatus> hookStatuses() const;
110	
111	    /// 成功挂载的 hook 名列表，形如 "mgmt_device_disconnected,hci_disconnect"
112	    std::string attachedHooksSummary() const;
113	
114	    /// 最近一次错误信息
115	    std::string lastError() const;
116	
117	    /// 已从 ringbuf 消费的原始观测条数
118	    uint64_t observationsConsumed() const { return observations_consumed_.load(); }
119	
120	    /// 已定案并写入 store 的 canonical 事件条数
121	    uint64_t eventsEmitted() const { return events_emitted_.load(); }
122	
123	    /// 归一化后取走事件（供上层周期性调用；内部已按窗口刷出）
124	    std::vector<WirelessDeviceEvent> drainNormalizedEvents();
125	
126	    /// 归一化器只读访问（诊断/测试）
127	    const BtEventNormalizer& normalizer() const { return normalizer_; }
