static __always_inline int is_session_enabled(const struct device_key *k)
{
    struct session_control *ctrl = bpf_map_lookup_elem(&active_sessions, k);
    if (!ctrl) return 0;  // 用户态未配置此设备（可能还没被 D-Bus 发现）
    return ctrl->enabled;
