bool saveMonitorOverrides(std::string& result, std::string& errorMsg) {
    if (!isConnected()) return fail("客户端未连接", errorMsg);
    return requestStringData(kMethodSaveMonitorOverrides, "保存监控器 override", result, errorMsg);
