bool setMonitorParam(const std::string& key, const std::string& value,
                     std::string& result, std::string& errorMsg) {
    if (!isConnected()) return fail("客户端未连接", errorMsg);

    DBusMessage* msg = dbus_message_new_method_call(kBusName, kObjectPath, kInterface, kMethodSetMonitorParam);
    if (!msg) {
        errorMsg = "创建方法调用消息失败";
        return false;
    }

    DBusMessageIter args;
    dbus_message_iter_init_append(msg, &args);
    const char* key_cstr = key.c_str();
    const char* value_cstr = value.c_str();
    dbus_message_iter_append_basic(&args, DBUS_TYPE_STRING, &key_cstr);
    dbus_message_iter_append_basic(&args, DBUS_TYPE_STRING, &value_cstr);

    DBusError err;
    dbus_error_init(&err);
    DBusMessage* reply = dbus_connection_send_with_reply_and_block(conn_, msg, 5000, &err);
    dbus_message_unref(msg);

    if (dbus_error_is_set(&err)) {
        errorMsg = "SetMonitorParam 失败: " + std::string(err.message);
        dbus_error_free(&err);
        return false;
    }
    if (!reply) {
        errorMsg = "未收到 SetMonitorParam 应答";
        return false;
    }

    // 解析回复（单个字符串 "ok"）
    DBusMessageIter iter;
    dbus_message_iter_init(reply, &iter);
    if (dbus_message_iter_get_arg_type(&iter) == DBUS_TYPE_STRING) {
        const char* s = nullptr;
        dbus_message_iter_get_basic(&iter, &s);
        result = s ? s : "";
    }

/**
 * @file common.hpp
 * @brief D-Bus 服务常量与全局配置定义
 *
 * 集中管理服务标识（bus name / object path / interface）、
 * 方法名、信号名以及运行时可配置的路径常量。
 * 路径常量支持通过环境变量覆盖，便于交叉编译部署和测试。
 *
 * 线程安全：本文件所有静态/inline 常量在编译期初始化，
 * 首次访问时求值（函数体风格的 lambda），无需额外锁。
 */

#pragma once

#include <string>

namespace weaknet_dbus {

// ==================== D-Bus 基础标识 ====================
// 这三个值共同决定了 D-Bus 服务的寻址三元组：BusName.ObjectPath.Interface
// 客户端必须使用完全相同的值才能正确连接到服务端

static constexpr const char kBusName[]     = "com.example.WeakNet";   ///< 服务名（唯一，由 dbus_bus_request_name 注册）
static constexpr const char kObjectPath[]  = "/com/example/WeakNet"; ///< 对象路径（类似文件系统，必须以 / 开头）
static constexpr const char kInterface[]    = "com.example.WeakNet"; ///< 接口名（方法和信号的命名空间）

// ==================== D-Bus 方法名 ====================
// 每个方法对应 DbusService 中一个 handleXxx 成员函数实现
// 客户端通过 dbus_message_new_method_call(..., kMethodXxx) 发起调用

static constexpr const char kMethodListInterfaces[]          = "ListInterfaces";      ///< 返回所有可用接口名的字符串数组
static constexpr const char kMethodGetInterfaces[]           = "GetInterfaces";      ///< ListInterfaces 的同义名（向后兼容）
static constexpr const char kMethodHealthCheck[]            = "HealthCheck";        ///< 执行网络健康检查，返回 JSON 格式诊断结果
static constexpr const char kMethodGetDiagnosis[]          = "GetDiagnosis";       ///< 查询端侧确定性机器诊断事实（DiagnosisFacts JSON）
static constexpr const char kMethodExecuteAction[]          = "ExecuteAction";      ///< 通过 ActionRegistry 执行安全动作（posix_spawn 隔离）
static constexpr const char kMethodPing[]                   = "Ping";               ///< 对指定主机执行 ICMP Ping，返回延迟和丢包
static constexpr const char kMethodGetBluetoothDevices[]    = "GetBluetoothDevices";///< 返回已发现蓝牙设备列表（BlueZ D-Bus）
static constexpr const char kMethodGetBluetoothAdapter[]     = "GetBluetoothAdapter";///< 返回蓝牙适配器状态（是否可用、是否在连接中）
static constexpr const char kMethodGetBluetoothAudioQuality[] = "GetBluetoothAudioQuality"; ///< 查询蓝牙 A2DP 音频质量与 eBPF 融合诊断（JSON）
static constexpr const char kMethodGetCoexistenceConflict[]  = "GetCoexistenceConflict";
static constexpr const char kMethodGetNetworkExperience[] = "GetNetworkExperience";   ///< 查询 Wi-Fi 与蓝牙 2.4GHz 共存冲突与根因分析（JSON）
static constexpr const char kMethodGetDnsStats[]            = "GetDnsStats";        ///< 查询 DNS eBPF 监控的最近统计（平均延迟、超时率）
static constexpr const char kMethodGetWifiLossStats[]        = "GetWifiLossStats";   ///< 查询 Wi-Fi eBPF 丢包归因（按 ifindex）
static constexpr const char kMethodGetHttpLatencyStats[]    = "GetHttpLatencyStats";///< 查询 HTTP eBPF 请求延迟统计（p50/p99/慢请求）
static constexpr const char kMethodGetProcessProfiling[]    = "GetProcessProfiling";///< 查询 eBPF 进程网络画像（Top N 带宽进程）
static constexpr const char kMethodGetSkbDropStats[]        = "GetSkbDropStats";    ///< 查询 Socket/skb 丢包原因精确归因统计（JSON）
static constexpr const char kMethodGetTcpRttStats[]         = "GetTcpRttStats";     ///< 查询被动 TCP RTT 与拥塞统计（JSON）
static constexpr const char kMethodGetEbpfMonitorHealth[]   = "GetEbpfMonitorHealth";///< 查询所有 eBPF 监控器健康状态（是否成功加载）
static constexpr const char kMethodGetHistory[]              = "GetHistory";         ///< 查询 SQLite 历史快照（支持时间范围和网卡过滤）
static constexpr const char kMethodQueryDeviceEvents[]      = "QueryDeviceEvents";  ///< 查询规范化无线设备事件（时间范围/设备/类型过滤）
static constexpr const char kMethodQueryBtDataPath[]        = "QueryBtDataPath";    ///< 查询工业蓝牙数传链路流量指标（Phase 1b：时间/设备过滤）
static constexpr const char kMethodQuerySiteIncidents[]     = "QuerySiteIncidents"; ///< 查询区域级异常事件 SiteIncident（Phase 3a：区域层）
static constexpr const char kMethodSetMonitorParam[]         = "SetMonitorParam";   ///< 运行时设置监控器参数（白名单校验+原子提交）
static constexpr const char kMethodGetMonitorParam[]         = "GetMonitorParam";   ///< 查询监控器当前参数（JSON 格式）
static constexpr const char kMethodListMonitors[]             = "ListMonitors";
static constexpr const char kMethodGetMonitorStatus[]         = "GetMonitorStatus";
static constexpr const char kMethodEnableMonitor[]            = "EnableMonitor";
static constexpr const char kMethodDisableMonitor[]           = "DisableMonitor";
static constexpr const char kMethodRestartMonitor[]           = "RestartMonitor";
static constexpr const char kMethodSaveMonitorOverrides[]     = "SaveMonitorOverrides";

// ==================== 信号名 ====================
// 服务端主动向订阅客户端推送事件。客户端通过 dbus_bus_add_match 过滤感兴趣的信号

static constexpr const char kSignalChanged[]                = "Changed";                ///< 通用变化信号（文本消息 + 计数器，旧版兼容）
static constexpr const char kSignalInterfaceChanged[]       = "InterfaceChanged";       ///< 网卡添加/删除事件
static constexpr const char kSignalConnectionModeChanged[]  = "ConnectionModeChanged";  ///< 当前上网网卡切换事件
static constexpr const char kSignalNetworkQualityChanged[]  = "NetworkQualityChanged";  ///< 综合网络质量（Excellent/Good/Fair/Poor）变化
static constexpr const char kSignalBluetoothDeviceChanged[] = "BluetoothDeviceChanged"; ///< 蓝牙设备出现/消失/状态变化
static constexpr const char kSignalMonitorStateChanged[]    = "MonitorStateChanged";
///< eBPF 监控器聚合指标推送（JSON：monitor + 该监控器的关键统计 + 驱逐差分）
static constexpr const char kSignalEbpfMonitorStats[]       = "EbpfMonitorStats";

// ==================== 运行时路径常量 ====================

/// SQLite 历史数据持久化路径解析函数。
/// 见 kDatabasePath 注释。
inline std::string resolveDatabasePath(const std::string& cfg_data_dir) {
    if (!cfg_data_dir.empty()) {
        return cfg_data_dir + "/history.db";
    }
    const char* env = std::getenv("WEAKNET_DATA_DIR");
    if (env && *env) {
        return std::string(env) + "/history.db";
    }
    return std::string("/home/radxa/weaknet/data") + "/history.db";
}

/// 网络代次状态文件路径。与 history.db 同目录 —— 二者都是"这台设备的
/// 持久身份"，放在一起才能保证备份/迁移时不会只带走一半。
inline std::string resolveNetworkEpochPath(const std::string& cfg_data_dir) {
    return resolveDatabasePath(cfg_data_dir).substr(
               0, resolveDatabasePath(cfg_data_dir).size() - std::string("history.db").size()) +
           "network-epoch";
}

/// 默认流量分析接口名。空字符串 "" 表示自动选择当前活动接口
/// 可通过 WEAKNET_TRAFFIC_IFACE 覆盖（如 WEAKNET_TRAFFIC_IFACE=eth1 强制分析指定网卡）
inline const std::string kDefaultTrafficInterface = []() {
    const char* env = std::getenv("WEAKNET_TRAFFIC_IFACE");
    return env ? env : "";
}();

/// Changed 信号序列化输出文件路径
/// 使用 $XDG_RUNTIME_DIR 私有目录（通常是 /run/user/$UID），防符号链接攻击
/// 若 XDG_RUNTIME_DIR 未设置则退回到 /tmp（开发环境兼容）
inline const std::string kSignalSerializedFile = []() {
    const char* xdg = std::getenv("XDG_RUNTIME_DIR");
    return std::string(xdg ? xdg : "/tmp") + "/weaknet/signal_changed.bin";
}();

}  // namespace weaknet_dbus

/**
 * @file dbus_service.hpp
 * @brief D-Bus 服务层：方法处理 + 信号发射
 *
 * DbusService 封装了 libdbus-1 C API 的样板代码，提供：
 *   - register_on_connection() 将自身方法表注册到 DBusConnection
 *   - emitChanged() / emitSpecificSignal() 发射主动通知信号
 *   - handleXxx() 系列方法：供静态回调函数转发调用（避免头文件暴露 dbus 类型）
 *
 * 设计模式：
 *   D-Bus 要求回调函数签名为自由函数，且不允许捕获 this。
 *   因此使用静态函数 MessageHandlerStatic → 从 DBusConnection user_data
 *   取回 DbusService* → 调用成员函数 handleXxx。
 *
 * 线程安全：
 *   send_mutex_ 保护对同一 DBusConnection 的并发信号发射写操作
 *   （libdbus-1 的部分内部结构在多线程写入下不安全）
 */

#pragma once

#include <string>
#include <vector>
#include <mutex>

struct DBusConnection;
struct DBusMessage;

// 前置声明监控器类型（仅用于指针成员，避免头文件依赖）
namespace weaknet_dbus {
class DnsMonitor;
class WifiPacketLossMonitor;
class HttpLatencyMonitor;
class ProcessNetProfiler;
}

namespace weaknet_dbus {

class ServerContext;  ///< 前置声明

/**
 * @brief D-Bus 服务实现
 *
 * 构造时接收 ServerContext 指针（非 owning），
 * 所有 handleXxx 方法通过 ctx_ 访问 weak_mgr / bt_monitor / eBPF 监控器。
 */
class DbusService {
public:
    /**
     * @brief 构造：绑定 ServerContext
     * @param ctx 全局上下文（非 owning，必须在 DbusService 析构前保持有效）
     */
    explicit DbusService(ServerContext* ctx);

    ~DbusService() = default;

    /**
     * @brief 注册方法分发器到 D-Bus 连接
     *
     * 注册 kObjectPath 对象路径和 kMethodXxx 方法的分发回调。
     * 内部通过 dbus_connection_add_filter 安装一个全局过滤器，
     * 在过滤器中通过 DBUS_MESSAGE_TYPE_METHOD_CALL 判断并路由。
     *
     * @param conn 已注册服务名的 DBusConnection
     * @return true 注册成功，false 失败（通常是 conn 为空）
     */
    bool register_on_connection(DBusConnection* conn);

    // ---------- 信号发射接口 ----------

    /**
     * @brief 发射通用 Changed 信号
     *
     * 携带 message（文本）和 counter（单调递增计数器，调试用）。
     * 这是旧版兼容信号，新功能应使用 emitSpecificSignal 指定更精确的信号名。
     *
     * @param message 信号载荷文本
     * @param counter 计数器值（通常由 EventManager 维护）
     * @return true 发射成功
     */
    bool emitChanged(const std::string& message, int32_t counter);

    /**
     * @brief 发射指定类型的事件信号
     *
     * 支持 kSignalInterfaceChanged / kSignalBluetoothDeviceChanged 等所有具体信号名。
     * 内部实现带 2 次重试（间隔 10ms），应对 D-Bus daemon 短暂不可用。
     *
     * @param signalName 信号名（必须是 common.hpp 中定义的常量之一）
     * @param message    信号载荷文本
     * @param counter    事件计数器
     * @return true 至少一次发射成功
     */
    bool emitSpecificSignal(const std::string& signalName, const std::string& message, int32_t counter);

    /**
     * @brief 发射带详细信息的 NetworkQualityChanged 信号
     *
     * 与通用信号不同，此方法携带两个字符串载荷（message + details），
     * details 为 JSON 格式，包含各维度指标和权重评分。
     *
     * @param message 简短描述（如 "Quality changed to GOOD"）
     * @param details JSON 格式详细信息
     * @param counter 事件计数器
     */
    bool emitNetworkQualitySignal(const std::string& message, const std::string& details, int32_t counter);

    // ---------- 方法实现（供静态分发函数调用） ----------

    // 基础查询方法
    bool handleListInterfaces(DBusConnection* conn, DBusMessage* msg);       ///< ListInterfaces: 返回网卡名数组
    bool handleHealthCheck(DBusConnection* conn, DBusMessage* msg);          ///< HealthCheck: 执行完整健康检查
    bool handleGetDiagnosis(DBusConnection* conn, DBusMessage* msg);         ///< GetDiagnosis: 返回端侧确定性机器诊断事实 JSON
    bool handleExecuteAction(DBusConnection* conn, DBusMessage* msg);        ///< ExecuteAction: 执行白名单安全动作
    bool handlePing(DBusConnection* conn, DBusMessage* msg);                 ///< Ping: 对指定主机执行 ICMP

    // 蓝牙相关方法
    bool handleGetBluetoothDevices(DBusConnection* conn, DBusMessage* msg);   ///< GetBluetoothDevices: 返回设备列表
    bool handleGetBluetoothAdapter(DBusConnection* conn, DBusMessage* msg);   ///< GetBluetoothAdapter: 返回适配器状态
    bool handleGetBluetoothAudioQuality(DBusConnection* conn, DBusMessage* msg); ///< GetBluetoothAudioQuality: 返回指定设备音频质量与 eBPF 融合诊断 JSON
    bool handleQueryDeviceEvents(DBusConnection* conn, DBusMessage* msg);     ///< QueryDeviceEvents: 查询规范化无线设备事件（只读）
    bool handleQueryBtDataPath(DBusConnection* conn, DBusMessage* msg);       ///< QueryBtDataPath: 查询工业蓝牙数据通道历史指标（Phase 1b）
    bool handleQuerySiteIncidents(DBusConnection* conn, DBusMessage* msg);    ///< QuerySiteIncidents: 查询区域级异常事件（Phase 3a，只读）
    bool handleGetCoexistenceConflict(DBusConnection* conn, DBusMessage* msg);
    bool handleGetNetworkExperience(DBusConnection* conn, DBusMessage* msg);          ///< GetNetworkExperience: 返回 schema v2 权威评估快照（只读，不重新 evaluate）   ///< GetCoexistenceConflict: 返回 Wi-Fi 与蓝牙 2.4GHz 冲突诊断 JSON

    // eBPF 监控数据方法
    bool handleGetDnsStats(DBusConnection* conn, DBusMessage* msg);           ///< GetDnsStats: DNS 监控最近统计
    bool handleGetWifiLossStats(DBusConnection* conn, DBusMessage* msg);      ///< GetWifiLossStats: Wi-Fi 丢包归因
    bool handleGetHttpLatencyStats(DBusConnection* conn, DBusMessage* msg);  ///< GetHttpLatencyStats: HTTP TTFB 统计
    bool handleGetProcessProfiling(DBusConnection* conn, DBusMessage* msg);  ///< GetProcessProfiling: 进程画像
    bool handleGetSkbDropStats(DBusConnection* conn, DBusMessage* msg);      ///< GetSkbDropStats: Socket/skb 丢包归因
    bool handleGetTcpRttStats(DBusConnection* conn, DBusMessage* msg);       ///< GetTcpRttStats: 被动 TCP RTT 统计
    bool handleGetEbpfMonitorHealth(DBusConnection* conn, DBusMessage* msg);  ///< GetEbpfMonitorHealth: 各监控器健康状态

    // 历史数据
    bool handleGetHistory(DBusConnection* conn, DBusMessage* msg);            ///< GetHistory: SQLite 历史查询

    // 运行时配置
    bool handleSetMonitorParam(DBusConnection* conn, DBusMessage* msg);       ///< SetMonitorParam: 校验+原子提交
    bool handleGetMonitorParam(DBusConnection* conn, DBusMessage* msg);       ///< GetMonitorParam: 返回 JSON

    // 监控器生命周期控制
    bool handleListMonitors(DBusConnection* conn, DBusMessage* msg);
    bool handleGetMonitorStatus(DBusConnection* conn, DBusMessage* msg);
    bool handleEnableMonitor(DBusConnection* conn, DBusMessage* msg);
    bool handleDisableMonitor(DBusConnection* conn, DBusMessage* msg);
    bool handleRestartMonitor(DBusConnection* conn, DBusMessage* msg);
    bool handleSaveMonitorOverrides(DBusConnection* conn, DBusMessage* msg);

    bool handleMonitorOperation(DBusConnection* conn, DBusMessage* msg,
                                const char* operation);

private:
    /**
     * @brief 内部辅助：要求调用方为 root (UID 0)，否则回 ACCESS_DENIED 并返回 false。
     *
     * 用于所有"改变设备行为"的方法（执行动作、运行时调参、监控器生命周期）。
     * 这些方法会改变设备主动连接谁、探测频率或评估是否运行，而
     * `com.example.WeakNet.conf` 的 default 上下文允许任意本地用户发送调用，
     * 因此必须逐方法校验，不能只依赖总线策略。
     *
     * 只读查询方法（Get/HealthCheck/GetDiagnosis 等）不调用本函数。
     */
    bool requireRootCaller(DBusConnection* conn, DBusMessage* msg, const char* method_name);

    /**
     * @brief 内部辅助：向调用方回复字符串数组
     * @param conn D-Bus 连接
     * @param msg  原始方法调用消息（用于创建 reply）
     * @param arr  要返回的字符串数组
     */
    bool replyStringArray(DBusConnection* conn, DBusMessage* msg, const std::vector<std::string>& arr);

    /**
     * @brief 发射 D-Bus 信号（带重试的底层实现）
     *
     * @param signalName 信号名
     * @param args       可变载荷（每个 pair 的 first 是 D-Bus 类型字符，second 是指向值的指针）
     *                   支持 's' (string) / 'i' (int32_t) / 'u' (uint32_t)
     * @param counter    事件计数器
     */
    bool sendSignalInternal(const std::string& signalName,
                            const std::vector<std::pair<int, const void*>>& args,
                            int32_t counter);

private:
    ServerContext* ctx_;     ///< 全局上下文非 owning 指针
    std::mutex send_mutex_; ///< 保护对同一 DBusConnection 的并发信号写（libdbus-1 线程安全边界）
};

}  // namespace weaknet_dbus

/**
 * @file database_manager.hpp
 * @brief SQLite 历史数据持久化管理器
 *
 * 负责将 NetInfo 快照定期写入 SQLite，供客户端通过 D-Bus 历史查询接口取回。
 * 使用 prepared statement 避免 SQL 注入；忙时等待（busy_timeout=5000ms）避免多线程并发写冲突。
 *
 * 表结构（单表 network_history）：
 *   ts TEXT NOT NULL,                  -- ISO 8601 快照时间
 *   iface TEXT NOT NULL,               -- 接口名
 *   rtt_ms/jitter_ms/rssi_dbm REAL,    -- 指标值；stale 时为 SQL NULL
 *   rssi_status/rtt_status/jitter_status/tcp_loss_status/traffic_status TEXT,
 *                                       -- valid/unavailable/timeout/stale
 *   tcp_loss REAL, traffic_bps/pps/flows, -- 指标值
 *   data_version INTEGER,              -- 数据格式版本；当前为 2
 *   *_sample_ts INTEGER                -- 各指标 Unix 毫秒采样时间 */

#pragma once

#include <string>
#include <mutex>
#include <cstdint>
#include <optional>
#include <vector>

struct sqlite3;  ///< 前置声明 SQLite 句柄类型

namespace weaknet_dbus {

class NetInfo;  ///< 前置声明
struct NetworkQualityResult;  ///< 前置声明
struct WirelessDeviceEvent;  ///< 前置声明（Phase 3a 启动回放）
struct SiteIncident;         ///< 前置声明（Phase 4a 无线事实上行）
struct DeviceLinkProfile;    ///< 前置声明（Phase 4a 无线事实上行）

/**
 * @brief SQLite 历史数据持久化管理器
 *
 * 不可拷贝（sqlite3* 资源所有权语义）。
 * 线程安全：所有写入操作通过 write_mutex_ 保护。
 * 读取操作（queryHistory）内部可能开启自己的访问模式，但当前实现也走 write_mutex_ 简化处理。
 */
class DatabaseManager {
public:
    /**
     * @brief 打开（或创建）SQLite 数据库文件
     *
     * @param db_path 数据库文件完整路径（目录必须已存在）
     */
    explicit DatabaseManager(const std::string& db_path);
    ~DatabaseManager();

    DatabaseManager(const DatabaseManager&) = delete;
    DatabaseManager& operator=(const DatabaseManager&) = delete;

    /// 数据库连接是否成功建立
    bool isOpen() const;

    /**
     * @brief 写入一条快照记录
     *
     * 由 history_persistence_thread 每 5 分钟对每个 NetInfo 调用一次。
     * 内部使用 prepared statement 避免 SQL 注入。
     *
     * @param iface  接口名（NetInfo::ifName()）
     * @param info   完整 NetInfo 快照
     * @param score  综合质量评分（由 NetworkQualityAssessor 计算，0.0 表示未评分）
     * @param assessment_profile 写出该行时的评估 Profile 字符串
     *        （"NETWORK_ONLY"/"INTERNET_ACCESS"）。此前恒写死 INTERNET_ACCESS，
     *        设备实际跑 NETWORK_ONLY 时历史审计元数据是错的。
     */
    bool insertSnapshot(const std::string& iface, const NetInfo& info,
                        const NetworkQualityResult& overall,
                        uint64_t generation = 0,
                        int64_t snapshot_ts_ms = 0,
                        int64_t rtt_sample_ts = 0,
                        int64_t rssi_sample_ts = 0,
                        int64_t jitter_sample_ts = 0,
                        int64_t tcp_loss_sample_ts = 0,
                        int64_t traffic_sample_ts = 0,
                        const char* assessment_profile = "UNSPECIFIED");

    /**
     * @brief 查询历史快照，返回 JSON 数组字符串
     *
     * @param interface  接口过滤："" 表示所有网卡
     * @param start      起始时间（ISO 8601），"" 表示不限
     * @param end        结束时间（ISO 8601），"" 表示不限
     * @param limit      最大返回行数（默认 100）
     * @return JSON 数组（失败时返回 "[]"）
     */
    std::string queryHistory(const std::string& interface,
                             const std::string& start,
                             const std::string& end,
                             int limit = 100);

    /**
     * @brief 写入蓝牙与音频时序快照
     */
    bool insertBtSnapshot(const std::string& adapter_mac,
                          const std::string& device_mac,
                          const std::string& device_name,
                          bool connected,
                          int16_t rssi_dbm,
                          double distance_m,
                          bool audio_active,
                          double quality_score,
                          bool suspected_stall,
                          uint64_t bytes_per_sec = 0,
                          uint64_t max_gap_ms = 0);

    /**
     * @brief 查询蓝牙历史时序数据，返回 JSON 数组字符串
     * @param device_mac 设备 MAC 过滤，"" 表示所有设备
     * @param start      起始时间（ISO 8601），"" 表示不限
     * @param end        结束时间（ISO 8601），"" 表示不限
     * @param limit      最大行数
     * @return JSON 数组字符串
     */
    std::string queryBtHistory(const std::string& device_mac,
                               const std::string& start,
                               const std::string& end,
                               int limit = 100);

    /**
     * @brief 写入一条规范化无线设备事件
     *
     * 由 WirelessEventStore 调用。与 insertBtSnapshot 的语义区别：
     * 后者写的是"周期采样快照"，本方法写的是"事件"（只在断连/发现/劣化时发生）。
     *
     * 关于 NULL 语义：rssi_dbm 用 optional 表达"未采集"，写库为 SQL NULL；
     * 用 0 冒充未采集会污染后续 RSSI 统计。suspected_cause 同理（Phase 1 恒为空）。
     *
     * @param event_id       全局唯一事件 ID
     * @param ts_ms          事件时刻（Unix 毫秒）
     * @param site_id        现场身份（事件来源）
     * @param gateway_id     网关身份（事件来源）
     * @param protocol       协议族字符串（如 "BLUETOOTH"）
     * @param device_address 设备地址
     * @param address_type   地址类型字符串（如 "LE_PUBLIC"）
     * @param hci_index      HCI 适配器序号
     * @param event_type     事件类型字符串（如 "LINK_DISCONNECTED"）
     * @param rssi_dbm       事件时刻 RSSI；nullopt 表示未采集（写 NULL）
     * @param raw_reason_code 内核原始 HCI reason（无损保存）
     * @param reason         归一化原因字符串
     * @param source         证据来源字符串
     * @param source_detail  精确 hook 名
     * @param suspected_cause 推断原因；nullopt 写 NULL
     * @param details_json   审计性证据（raw_evidence 数组）
     * @return true 写入成功
     */
    bool insertDeviceEvent(const std::string& event_id,
                           int64_t ts_ms,
                           const std::string& site_id,
                           const std::string& gateway_id,
                           const std::string& protocol,
                           const std::string& device_address,
                           const std::string& address_type,
                           uint32_t hci_index,
                           const std::string& event_type,
                           const std::optional<int>& rssi_dbm,
                           uint8_t raw_reason_code,
                           const std::string& reason,
                           const std::string& source,
                           const std::string& source_detail,
                           const std::optional<std::string>& suspected_cause,
                           const std::string& details_json);

    /**
     * @brief 查询规范化无线设备事件，返回 JSON 数组字符串
     *
     * @param device_address 设备地址过滤，"" 表示所有设备
     * @param event_type     事件类型过滤（如 "LINK_DISCONNECTED"），"" 表示所有类型
     * @param start_ms       起始时间（Unix 毫秒），0 表示不限
     * @param end_ms         结束时间（Unix 毫秒），0 表示不限
