     */
    std::string queryDeviceBaselines(const std::string& device_address = "",
                                    int limit = 100);

    // ------------------------------------------------------------------
    // Phase 1b：工业蓝牙 HCI ACL 数据通道流量指标存储
    // ------------------------------------------------------------------

    /**
     * @brief 记录单条蓝牙数据通道周期指标快照
     * @param ts_ms 采样时刻（Unix 毫秒）
     * @param controller_id 控制器名（如 "hci0"）
