bool BtDataPathAnalyzer::readRawMapValue(uint16_t handle, RawAclTrafficVal* out) const {
    if (!out) return false;
    uint32_t key = handle & 0x0FFF;

    if (mapFd_ >= 0) {
        int ret = bpf_map_lookup_elem(mapFd_, &key, out);
        return (ret == 0);
    }

    // 内存测试桩回退
    auto it = mock_map_.find(handle & 0x0FFF);
    if (it != mock_map_.end()) {
        *out = it->second;
        return true;
    }
    return false;
}

