        const bool has_traffic = (obs.tx_bytes > 0 || obs.rx_bytes > 0);
        const double total_bps = obs.tx_throughput_bps + obs.rx_throughput_bps;

        // -----------------------------------------------------------------
        // 规则 1：BT_DATAPATH_ATTRIBUTION_LOST (归因丢失)
        // 存在真实控制器级传输，但未能绑定到具体设备 BDADDR
