size_t BtDataPathAnalyzer::pruneStaleEntries(const std::set<uint16_t>& live_handles) {
    std::lock_guard<std::mutex> lock(mutex_);
    size_t pruned = 0;

    // 内核 Map 条目遍历（key为复合 key 或裸 handle，取低 12 位判断）
