                    << anomaly.description);

        // 若已绑定具体设备，桥接生成一条规范化设备事件 (LinkDegraded) 注入事件存储
        if (!anomaly.device_address.empty() && ctx_->wireless_event_store) {
            WirelessDeviceEvent ev;
